// 答えは console.log で出力する
// ここに解答を書く

solution.code:
import { readFileSync } from "fs";

const [y, m, d] = readFileSync(0, "utf8").trim().split(" ").map(Number);

const leap = (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

// 前の月までの日数を足し、最後にその月の日を足す
let total = d;
for (let i = 0; i < m - 1; i++) total += days[i];
console.log(total);
